(() => {
	if (window.CollectionDisplay) return;

	const ROOT_SELECTOR = '[data-collection-display]';
	const VIEW_TOGGLE_SELECTOR = '[data-collection-view-toggle]';
	const DESKTOP_COLUMNS_SELECTOR = '[data-collection-desktop-columns]';
	const MOBILE_COLUMNS_SELECTOR = '[data-collection-mobile-columns]';

	const state = {
		view: 'products',
		desktopColumns: '2',
		mobileColumns: '2'
	};

	function getRoots() {
		return Array.from(document.querySelectorAll(ROOT_SELECTOR));
	}

	function readInitialState() {
		const root = getRoots()[0];
		if (!root) return;

		state.view = root.dataset.view === 'model' ? 'model' : 'products';
		state.desktopColumns = ['2', '4', '8'].includes(root.dataset.desktopColumns) ? root.dataset.desktopColumns : '2';
		state.mobileColumns = ['1', '2'].includes(root.dataset.mobileColumns) ? root.dataset.mobileColumns : '2';
	}

	function setPressed(root, selector, activeValue, dataKey) {
		root.querySelectorAll(selector).forEach((button) => {
			button.setAttribute('aria-pressed', button.dataset[dataKey] === activeValue ? 'true' : 'false');
		});
	}

	function applyState() {
		getRoots().forEach((root) => {
			root.dataset.view = state.view;
			root.dataset.desktopColumns = state.desktopColumns;
			root.dataset.mobileColumns = state.mobileColumns;
			root.style.setProperty('--collection-columns-desktop', state.desktopColumns);
			root.style.setProperty('--collection-columns-mobile', state.mobileColumns);

			root.querySelectorAll(VIEW_TOGGLE_SELECTOR).forEach((toggle) => {
				toggle.setAttribute('aria-checked', state.view === 'model' ? 'true' : 'false');
			});
			setPressed(root, DESKTOP_COLUMNS_SELECTOR, state.desktopColumns, 'collectionDesktopColumns');
			setPressed(root, MOBILE_COLUMNS_SELECTOR, state.mobileColumns, 'collectionMobileColumns');
		});
	}

	function handleClick(event) {
		const viewToggle = event.target.closest(VIEW_TOGGLE_SELECTOR);
		if (viewToggle) {
			state.view = state.view === 'model' ? 'products' : 'model';
			applyState();
			return;
		}

		const desktopButton = event.target.closest(DESKTOP_COLUMNS_SELECTOR);
		if (desktopButton) {
			state.desktopColumns = ['2', '4', '8'].includes(desktopButton.dataset.collectionDesktopColumns) ? desktopButton.dataset.collectionDesktopColumns : '2';
			applyState();
			return;
		}

		const mobileButton = event.target.closest(MOBILE_COLUMNS_SELECTOR);
		if (mobileButton) {
			state.mobileColumns = mobileButton.dataset.collectionMobileColumns === '2' ? '2' : '1';
			applyState();
		}
	}

	function init() {
		readInitialState();
		applyState();
		document.addEventListener('click', handleClick);
	}

	window.CollectionDisplay = {
		refresh: applyState
	};

	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', init, { once: true });
	} else {
		init();
	}
})();
